<template><view class="page"><AppHeader/><view class="content profile-grid"><view class="profile-intro"><view class="display">我的形象档案</view><view class="lead">每一次咨询，<br/>都让适合你的答案更清晰。</view><image class="image-monochrome" src="/static/design/consultation-side.webp" mode="aspectFill"/></view><view class="profile-main"><view class="profile-card"><image class="image-monochrome" src="/static/design/hero.webp" mode="aspectFill"/><view><text class="eyebrow">MY PROFILE</text><view class="section-title">私人形象档案</view><view class="lead">清晰而真实，是你独有的风格。</view><view class="traits">清晰轮廓　/　柔和质感　/　简洁线条　/　低维护</view></view><view class="palette"><text>我的风格色板</text><view><image v-for="x in colors" :key="x" :class="{selected:selectedColor===x}" :src="`/static/design/${x}-texture.webp`" @click="selectColor(x)"/></view><small v-if="selectedColor">已选择：{{colorNames[selectedColor]}}</small></view></view><view class="section-title domains-title">形象领域</view><view class="domain-list"><view v-for="(m,key) in modules" :key="key" @click="startModule(key)"><image class="image-monochrome" :src="images[key]" mode="aspectFill"/><view class="domain-shade"></view><text>{{m.name}}</text><small>{{history(key)?'已完成':'待开启'}}　→</small></view></view><view class="history-head"><view class="section-title">咨询记录</view><view class="editorial-btn" @click="start">开始新的咨询　→</view></view><view v-for="x in items" :key="x.id" class="history" @click="open(x.id)"><text>{{new Date(x.created_at).toLocaleDateString()}}</text><b>{{modules[x.module as keyof typeof modules]?.name}}咨询</b><text>查看详情　→</text></view></view></view></view></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{listConsultations,type Consultation}from'../../api';import{isLoggedIn,openLogin}from'../../auth';import{draft,modules}from'../../state';const items=ref<Consultation[]>([]),colors=['silver','fabric','black','wine'],colorNames:Record<string,string>={silver:'亮银',fabric:'柔白',black:'曜黑',wine:'酒红'},selectedColor=ref<string>(uni.getStorageSync('mirror_style_color')||'');const images:{[k:string]:string}={hair:'/static/design/profile-domain-hair.webp',skin:'/static/design/profile-domain-skin.webp',outfit:'/static/design/profile-domain-outfit-clean.png',makeup:'/static/design/profile-domain-makeup-clean.png',tryon:'/static/design/module-outfit.webp'};onMounted(async()=>{if(!isLoggedIn()){openLogin('profile');return}try{items.value=(await listConsultations()).items}catch{}});function history(k:string){return items.value.some(x=>x.module===k&&x.status==='succeeded')}function open(id:string){uni.navigateTo({url:`/pages/history-detail/index?id=${id}`})}function start(){isLoggedIn()?uni.navigateTo({url:'/pages/modules/index'}):openLogin('profile')}function startModule(key:string){if(!isLoggedIn()){openLogin(key==='tryon'?'tryon':'profile');return}draft.module=key;key==='tryon'?uni.switchTab({url:'/pages/tryon/index'}):uni.navigateTo({url:`/pages/preferences/index?module=${key}`})}function selectColor(color:string){selectedColor.value=color;uni.setStorageSync('mirror_style_color',color)}</script>
<style scoped>.profile-grid{display:grid;margin-top:30px}.profile-intro{position:relative;overflow:hidden;min-height:430px;padding:28px 22px}.profile-intro:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(247,248,249,.94) 0%,rgba(247,248,249,.72) 25%,rgba(247,248,249,.08) 62%,rgba(17,19,23,.16) 100%);pointer-events:none}.profile-intro .display,.profile-intro .lead{position:relative;z-index:2}.profile-intro image{position:absolute;inset:0;width:100%;height:100%;filter:grayscale(1)}.profile-main{background:rgba(255,255,255,.75);padding:25px}.profile-card{display:grid;gap:24px}.profile-card>image{width:100%;height:315px}.traits{margin-top:28px;font-family:"Songti SC",serif}.palette>text{font-family:"Songti SC",serif;font-size:19px}.palette view{display:flex;gap:7px;margin-top:20px}.palette image{width:70px;height:70px;cursor:pointer;transition:transform .18s,box-shadow .18s}.palette image.selected{transform:translateY(-3px);box-shadow:0 0 0 2px #fff,0 0 0 3px var(--wine)}.palette small{display:block;margin-top:12px;color:#777}.domains-title{margin-top:30px}.domain-list{display:grid;grid-template-columns:1fr 1fr;gap:10px}.domain-list>view{position:relative;height:145px;overflow:hidden;cursor:pointer;color:#fff}.domain-list image,.domain-shade{position:absolute;inset:0;width:100%;height:100%}.domain-shade{background:linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.7))}.domain-list text,.domain-list small{position:absolute;z-index:1;left:16px;display:block}.domain-list text{bottom:38px;font-family:"Songti SC",serif;font-size:17px}.domain-list small{bottom:16px;color:#eee}.history-head,.history{display:flex;align-items:center;justify-content:space-between;margin-top:30px}.history{border-top:1px solid var(--line);padding:18px 0;font-family:"Songti SC",serif}@media(min-width:900px){.profile-grid{grid-template-columns:330px 1fr}.profile-intro{min-height:780px;padding:18px}.profile-main{padding:34px}.profile-card{grid-template-columns:310px 1fr 330px}.domain-list{grid-template-columns:repeat(4,1fr)}}</style>
